import React from 'react';
import { View, Text, Pressable, StyleSheet, ScrollView, type ViewStyle } from 'react-native';

type Props = {
  title: string;
  subtitle?: string;
  onBack?: () => void;
  rightAction?: React.ReactNode;
  children: React.ReactNode;
  contentStyle?: ViewStyle;
};

export function ScreenLayout({ title, subtitle, onBack, rightAction, children, contentStyle }: Props) {
  return (
    <ScrollView contentContainerStyle={[styles.container, contentStyle]}>
      <View style={styles.header}>
        <View style={styles.headerText}>
          <Text style={styles.title}>{title}</Text>
          {subtitle ? <Text style={styles.subtitle}>{subtitle}</Text> : null}
        </View>
        <View style={styles.headerActions}>
          {rightAction}
          {onBack ? (
            <Pressable style={styles.backButton} onPress={onBack}>
              <Text style={styles.backButtonText}>Retour</Text>
            </Pressable>
          ) : null}
        </View>
      </View>

      {children}
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: { padding: 20, backgroundColor: '#F5F7FB' },
  header: { flexDirection: 'row', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: 16, gap: 12 },
  headerText: { flex: 1 },
  headerActions: { flexDirection: 'row', alignItems: 'center', gap: 8 },
  title: { fontSize: 24, fontWeight: '800', color: '#162033' },
  subtitle: { fontSize: 14, color: '#52627D', marginTop: 4 },
  backButton: { paddingVertical: 8, paddingHorizontal: 10, borderRadius: 12, backgroundColor: '#E6ECF7' },
  backButtonText: { color: '#1E3A8A', fontWeight: '700' },
});
